// Claude writes down what a session is about, and this is how a hook reads it.
//
// It is in this program rather than in core because every word of it is
// Claude's: the file and the line type (R10). Core is handed a name and never
// learns which of three places produced it.
package main

import (
	"bytes"
	"encoding/json"
	"strings"
)

// Claude titles a session itself, in the transcript:
//
//	~/.claude/projects/<slug>/<session-id>.jsonl
//	{"type":"ai-title","aiTitle":"Fix Sketchybar display on external monitors",…}
//
// It is generated by a side query — `querySource:"generate_session_title"`, a
// JSON-schema call returning `{title}`. What it produces is the only thing on
// the machine that reads like a person named the session: "Fix Sketchybar
// display on external monitors", "Remove option-n binding from sketchybar",
// "Build terminal-based Grafana-like dashboard with Kitty graphics".
//
// [verified 2026-11-24, 2.1.311] It is written again, and not where it used to
// be. 89 of the 311 transcripts on this machine hold one, and in 88 of them it
// is written several times, always the same title, the newest within 34 KiB of
// the end; the first lies inside the first 64 KiB in one. So it is read off the
// tail, in the pass usage.go already makes on every hook, newest first, and it
// rides every hook as the name does (D-137). A tail read that stops before it
// reaches a title reports none, and an empty name leaves the stored one alone.
// Until D-137 it was read off the head, once a turn, and found almost never
// (D-107).
//
// What is deliberately **not** read is the first prompt. It is always there and
// it says what the session is about, and it is still not a name: it is prose,
// it would have to be cut to fit anywhere, and reporting it would mean core
// could no longer tell a session nobody has named from one somebody did
// (D-75). An unnamed session reports nothing and core does the guessing.

// titleLine is the cheap test that decides whether a line is worth decoding.
// Most of a transcript is prompts, attachments and tool results, and one of
// them can be a megabyte long.
var titleLine = []byte(`"ai-title"`)

// titledLine is the part of one line this program reads. Claude writes a dozen
// more fields on every one of them and will write more.
type titledLine struct {
	Type    string `json:"type"`
	AITitle string `json:"aiTitle"`
}

// titleInLine reads one line, and says whether it is Claude's title for this
// session.
//
// Claude is appending to this file while this runs and the read may have landed
// mid-line, so a line that does not parse is ordinary and worth nothing more
// than moving on to the next one.
func titleInLine(line []byte) (string, bool) {
	if !bytes.Contains(line, titleLine) {
		return "", false
	}
	var written titledLine
	if err := json.Unmarshal(line, &written); err != nil {
		return "", false
	}
	if written.Type != "ai-title" {
		return "", false
	}
	title := strings.TrimSpace(written.AITitle)
	return title, title != ""
}
